import * as THREE from 'three';

// ---------- deterministic randomness and noise ----------
let rngState = 170;
function rand() {
  rngState = (rngState + 0x6D2B79F5) | 0;
  let t = Math.imul(rngState ^ (rngState >>> 15), 1 | rngState);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
const randRange = (min, max) => min + (max - min) * rand();
const clamp01 = (v) => Math.min(1, Math.max(0, v));
const smooth01 = (v) => { const c = clamp01(v); return c * c * (3 - 2 * c); };

function latticeHash(ix, iy) {
  let h = Math.imul(ix, 374761393) + Math.imul(iy, 668265263);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}
function valueNoise(x, y) {
  const ix = Math.floor(x), iy = Math.floor(y);
  const fx = smooth01(x - ix), fy = smooth01(y - iy);
  const top = latticeHash(ix, iy) * (1 - fx) + latticeHash(ix + 1, iy) * fx;
  const bottom = latticeHash(ix, iy + 1) * (1 - fx) + latticeHash(ix + 1, iy + 1) * fx;
  return top * (1 - fy) + bottom * fy;
}
function fbmNoise(x, y) {
  return valueNoise(x, y) * .55 + valueNoise(x * 2.1 + 7, y * 2.1 + 3) * .3 + valueNoise(x * 4.3 + 11, y * 4.3 + 5) * .15;
}

