const mainCamera = new THREE.PerspectiveCamera(40, 16 / 9, 1, 3200);

function fitCameraToViewport() {
  const aspect = window.innerWidth / window.innerHeight;
  // Keep pagoda and Fuji both in frame on narrow screens: guard horizontal half-FOV.
  const halfTan = Math.max(Math.tan(THREE.MathUtils.degToRad(20)), 0.56 / aspect);
